import Bubble from './chat-bubble.svelte';
import BubbleMessage from './chat-bubble-message.svelte';
import BubbleAvatar from './chat-bubble-avatar.svelte';
import List from './chat-list.svelte';
import * as Avatar from '$COMPONENTS$/ui/avatar';

const BubbleAvatarImage = Avatar.Image;
const BubbleAvatarFallback = Avatar.Fallback;

export { List, Bubble, BubbleMessage, BubbleAvatar, BubbleAvatarImage, BubbleAvatarFallback };

export type {
	ChatListPropsWithoutHTML,
	ChatListProps,
	ChatBubblePropsWithoutHTML,
	ChatBubbleProps,
	ChatBubbleMessagePropsWithoutHTML,
	ChatBubbleMessageProps
} from './types';

import type { WithChildren, WithoutChildren } from 'bits-ui';
import type { HTMLAttributes } from 'svelte/elements';

export type ChatListPropsWithoutHTML = WithChildren<{
	ref?: HTMLDivElement | null;
}>;

export type ChatListProps = ChatListPropsWithoutHTML &
	WithoutChildren<HTMLAttributes<HTMLDivElement>>;

export type ChatBubblePropsWithoutHTML = WithChildren<{
	ref?: HTMLDivElement | null;
	variant: 'sent' | 'received';
}>;

export type ChatBubbleProps = ChatBubblePropsWithoutHTML &
	WithoutChildren<HTMLAttributes<HTMLDivElement>>;

export type ChatBubbleMessagePropsWithoutHTML = WithChildren<{
	ref?: HTMLDivElement | null;
	typing?: boolean;
}>;

export type ChatBubbleMessageProps = ChatBubbleMessagePropsWithoutHTML &
	WithoutChildren<HTMLAttributes<HTMLDivElement>>;
